// ═══════════════════════════════════════════════════
//  glu50-gen — exports Glove50Embedder built-in
//  vocabulary to .gv50 compact binary format.
//
//  Build + run:
//    cd scripts/gv50-gen && dotnet run
//    dotnet run --project scripts/gv50-gen
//    dotnet run --project scripts/gv50-gen -- models/glove50d.gv50
// ═══════════════════════════════════════════════════

using System.Text;

var outputPath = args.Length > 0
    ? args[0]
    : Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "models", "glove50d.gv50");

// ── Build vocabulary (same as Glove50Embedder.BuildVocab) ──
var vocab = BuildVocab();
Console.WriteLine($"Vocabulary: {vocab.Count} words");

// Verify each word generates a valid non-zero vector
var verifyCount = 0;
var dimWarn = false;
foreach (var kv in vocab)
{
    if (kv.Value.Length != 50) { dimWarn = true; continue; }
    var sum = kv.Value.Sum(v => Math.Abs(v));
    if (sum < 0.001f) { Console.Error.WriteLine($"WARN: zero vector for '{kv.Key}'"); continue; }
    verifyCount++;
}
Console.WriteLine($"Verified: {verifyCount}/{vocab.Count} have non-zero vectors");

var dir = Path.GetDirectoryName(outputPath);
if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);

using var fs = new FileStream(outputPath, FileMode.Create, FileAccess.Write);
using var bw = new BinaryWriter(fs);

bw.Write(vocab.Count);
var buf = new byte[200];

foreach (var kv in vocab.OrderBy(kv => kv.Key))
{
    var wb = Encoding.UTF8.GetBytes(kv.Key);
    if (wb.Length > 255) continue;
    bw.Write((ushort)wb.Length);
    bw.Write(wb);
    Buffer.BlockCopy(kv.Value, 0, buf, 0, 200);
    bw.Write(buf);
}

var fi = new FileInfo(outputPath);
Console.WriteLine($"\nWritten: {fi.FullName}");
Console.WriteLine($"Size: {fi.Length:N0} bytes ({fi.Length / 1024.0:F1} KB)");
Console.WriteLine($"Words: {vocab.Count}");
Console.WriteLine($"\nRun:   dotnet run --project scripts/gv50-gen");
Console.WriteLine($"Usage: Glove50Embedder auto-loads from models/glove50d.gv50");

